SELECT TOP 50 DATETRUNC(MONTH, usage_events.start_time) AS [month], COUNT(usage_events.event_id) AS [event_count_count] FROM usage_events INNER JOIN customers ON RIGHT(REPLICATE('0', 10 - LEN(CAST(customers.cust_id AS VARCHAR))) + CAST(customers.cust_id AS VARCHAR), 10) = usage_events.client_no WHERE start_time >= CAST('2026-06-01T00:00:00.000000' AS DATETIME2) AND start_time < CAST('2026-11-01T00:00:00.000000' AS DATETIME2) AND customers.status = 'A' GROUP BY DATETRUNC(MONTH, usage_events.start_time)